// もとからある天気の場面に、天気の条件をつける（ほかの条件はそのまま）
const WX_TAGS = [
  [/ゲリラ豪雨|土砂降り/, 'heavy'],
  [/夕立|通り雨|にわか雨/, 'shower'],
  [/梅雨の晴れ間|洗濯物を干|洗濯物を一気に干|干し終えて|布団を干|乾いた洗濯物|洗濯物を取り込みながら|夕焼け|天の川|名月|日差し|日向ぼっこ|日当たりのいい|花火大会|手持ち花火|初日の出|星空/, 'dry'],
  [/雨の日|梅雨の雨|雨で|傘を剣|レインコート|カッパ|雨宿り/, 'rain'],
  [/炎天下|猛暑|熱中症|30度を超える|蒸し風呂|暑くて|暑さで|汗をかきながら|寝苦し|冷房の効きすぎ|扇風機の首振り/, 'hot'],
  [/霜を|凍結|冷え込んだ/, 'cold'],
  [/台風の接近|強風|風が強|木枯らし|春一番/, 'windy'],
  [/雪の降る|雪が降|しんしんと|粉雪が舞/, 'snow']
];

(function mergeExtra() {
  const add = (pool, arr) => { if (pool && arr) pool.push(...arr); };
  Object.entries(EXTRA_TX.sleep).forEach(([k, arr]) => add(SLEEP_TX[k], arr));
  add(EN_TX, EXTRA_TX.en);
  Object.entries(EXTRA_TX.school).forEach(([k, arr]) => add(SCHOOL_TX[k], arr));
  Object.entries(EXTRA_TX.off).forEach(([k, arr]) => add(OFF_TX[k], arr));
  Object.entries(EXTRA_TX.work).forEach(([k, arr]) => add(WORK_TX[k] || (WORK_TX[k] = []), arr));
  Object.entries(EXTRA_TX.night).forEach(([k, arr]) => add(NIGHT_TX[k] || (NIGHT_TX[k] = []), arr));
  Object.entries(EXTRA_TX.commute).forEach(([k, arr]) => add(COMMUTE_TX[k], arr));
  Object.entries(COMMUTE_FILL).forEach(([k, arr]) => add(COMMUTE_TX[k], arr));
  Object.entries(NIGHT_FILL).forEach(([k, arr]) => add(NIGHT_TX[k] || (NIGHT_TX[k] = []), arr));
  // 天気の場面
  Object.entries(WX_TX.off).forEach(([k, arr]) => add(OFF_TX[k], arr));
  Object.entries(WX_TX.commute).forEach(([k, arr]) => add(COMMUTE_TX[k], arr));
  Object.entries(WX_TX.work).forEach(([k, arr]) => add(WORK_TX[k] || (WORK_TX[k] = []), arr));
  Object.entries(WX_TX.school).forEach(([k, arr]) => add(SCHOOL_TX[k], arr));
  add(EN_TX, WX_TX.en);
  add(SLEEP_TX.any, WX_TX.sleep.filter(e => !(e[3].a && e[3].a[1] <= 12)));
  add(SLEEP_TX.kid, WX_TX.sleep.filter(e => e[3].a && e[3].a[1] <= 12));
  add(LUNCH_TX, WX_TX.lunch);
  add(SCHOOL_TX.elem, MONITOR_TX.elem);
  add(SCHOOL_TX.teen, MONITOR_TX.teen);

  // 夜勤は20時半ごろから始まるので、時刻の決まっていない「深夜」「夜明け前」の文は時間帯を絞る
  Object.values(NIGHT_TX).forEach(arr => arr.forEach((e, i) => {
    if (typeof e !== 'string') return;
    if (/夜明け前|明け方|まだ暗いうち/.test(e)) arr[i] = [3, 6.5, e];
    else if (/深夜|真夜中|終電/.test(e)) arr[i] = [22.5, 5, e];
  }));
  add(OFF_TX.baby, BOYS_TX.baby);
  add(EN_TX, BOYS_TX.en);
  add(SCHOOL_TX.elem, BOYS_TX.elem);
  add(SCHOOL_TX.teen, BOYS_TX.teen);
  add(OFF_TX.kid, BOYS_TX.kid);
  add(OFF_TX.student, BOYS_TX.student);
  add(SLEEP_TX.kid, BOYS_TX.sleep);
  add(SLEEP_TX.any, VARIETY_TX.sleep_any);
  add(SLEEP_TX.any, SNORE_TX);
  add(SLEEP_TX.youth, VARIETY_TX.sleep_youth);
  add(SLEEP_TX.kid, VARIETY_TX.sleep_kid);
  add(OFF_TX.adult, VARIETY_TX.adult);
  add(OFF_TX.senior, VARIETY_TX.senior);
  add(SCHOOL_TX.elem, SCHOOL_PLUS.elem);
  add(SCHOOL_TX.teen, SCHOOL_PLUS.teen);
  add(OFF_TX.student, SCHOOL_PLUS.student);
  add(OFF_TX.kid, SCHOOL_PLUS.kid);
  Object.entries(FILL_TX).forEach(([k, arr]) => add(OFF_TX[k], arr));
  add(OFF_TX.college, SCHOOL_PLUS.college);
  ['am', 'pm'].forEach(k => {
    COMMUTE_TX[k] = COMMUTE_TX[k].map(e => {
      const text = typeof e === 'string' ? e : e[2];
      const mode = COMMUTE_MODE_OF[text];
      if (!mode) return e;
      if (typeof e === 'string') return [0, 24, e, { mode }];
      return [e[0], e[1], e[2], Object.assign({ mode }, e[3] || {})];
    });
  });
  // 天気の条件づけは、すべての文を合流させたあとに行う
  const tagWx = arr => arr.forEach((e, i) => {
    const x = typeof e === 'string' ? e : e[2];
    if (typeof x !== 'string' || /夏期講習/.test(x)) return;
    // 雨上がりの文は、いま降っていないときだけ。積もった雪で遊ぶ文は、雨の日には出さない
    if (/雨上がり/.test(x) || /積もった雪|雪が積もった|雪玉|雪合戦|雪だるま|新雪/.test(x)) {
      const k = /雨上がり/.test(x) ? 'dry' : ['dry', 'snow'];
      if (typeof e === 'string') arr[i] = [0, 24, e, { wx: k }];
      else if (!(e[3] && e[3].wx)) e[3] = Object.assign({}, e[3] || {}, { wx: k });
      return;
    }
    const hit = WX_TAGS.find(([re]) => re.test(x));
    if (!hit) return;
    if (typeof e === 'string') arr[i] = [0, 24, e, { wx: hit[1] }];
    else if (!(e[3] && e[3].wx)) e[3] = Object.assign({}, e[3] || {}, { wx: hit[1] });
  });
  [OFF_TX, COMMUTE_TX, WORK_TX, NIGHT_TX, SCHOOL_TX, SLEEP_TX].forEach(pools => Object.values(pools).forEach(tagWx));
  tagWx(EN_TX); tagWx(LUNCH_TX);
})();


