(function mergeWind() {
  const add = (pool, arr) => { if (pool && arr) pool.push(...arr); };
  Object.entries(WIND_TX.off).forEach(([k, arr]) => add(OFF_TX[k], arr));
  Object.entries(WIND_TX.school).forEach(([k, arr]) => add(SCHOOL_TX[k], arr));
  add(EN_TX, WIND_TX.en);
  Object.entries(WIND_TX.commute).forEach(([k, arr]) => add(COMMUTE_TX[k], arr));
  Object.entries(WIND_TX.work).forEach(([k, arr]) => add(WORK_TX[k] || (WORK_TX[k] = []), arr));
  add(LUNCH_TX, WIND_TX.lunch);
  Object.entries(WIND_TX.sleep).forEach(([k, arr]) => add(SLEEP_TX[k], arr));
})();

