// 昼勤・夜勤で使える場面は WORK_TX の同じ項目を参照する。
const NIGHT_JOB_TX = {};
(function shareWorkScenes() {
  const assign = (jobs, entry) => {
    jobs.forEach(name => { NIGHT_JOB_TX[name] = [entry]; });
  };
  const add = (jobs, text) => {
    const tag = JOBS.find(j => j[0] === jobs[0])[4];
    const entry = [0, 24, text, { a: [18, 109], jobs }];
    WORK_TX[tag].push(entry);
    assign(jobs, entry);
  };
  // 既存文を流用。時刻だけで制限されていた通常作業は終日勤務に対応させる。
  const reuse = (jobs, text) => {
    const tag = JOBS.find(j => j[0] === jobs[0])[4];
    const entry = WORK_TX[tag].find(e => (typeof e === 'string' ? e : e[2]) === text);
    if (!entry || typeof entry === 'string') throw new Error('共用する仕事の文が見つかりません: ' + text);
    entry[0] = 0; entry[1] = 24;
    assign(jobs, entry);
  };
  add(['ITエンジニア', 'システムエンジニア'], '届いたアラートの原因を調べているところでした');
  reuse(['薬剤師'], '処方された薬を数えながら、ダブルチェックしているところでした');
  reuse(['臨床検査技師'], '検査室で、届いた血液の検体を分析装置にセットしているところでした');
  add(['獣医師'], '診察室で、運ばれてきた犬の様子を飼い主から聞いているところでした');
  add(['看護助手'], '看護師と一緒に、患者さんの体位を変えているところでした');
  reuse(['物流センターの事務'], '配送の遅れの問い合わせに、追跡番号を調べながら答えているところでした');
  reuse(['コールセンターのオペレーター'], '電話を切ったとたん次の着信が鳴り、深呼吸して受けたところでした');
  add(['ビル清掃員'], '廊下の床を洗浄機で磨いているところでした');
  add(['ごみ収集作業員'], '収集ルートを回り、店先に出されたごみを積み込んでいるところでした');
  add(['電気工事士', '配管工', '現場監督', '土木技術者'], '工事現場で、作業の進み具合を確かめているところでした');
  reuse(['フォークリフトのオペレーター'], 'トラックの荷台から、フォークリフトで荷物を降ろしているところでした');
  reuse(['商品の梱包スタッフ'], 'テープで閉じた段ボールに、送り状を貼り付けたところでした');
  reuse(['船員'], '船のブリッジで、海図にいまの位置を書き込んでいるところでした');
  add(['金属加工の職人', '電子部品の検査員', '印刷工', '溶接工', '品質管理の担当者', '縫製工場の作業員'], '作業を区切り、次の班に引き継ぐ内容を記録しているところでした');
})();

